const guides={
 E:{title:'在交流中推进',meaning:'你的回答更偏向通过互动组织想法。讨论、即时反馈与共同推进，可能帮助你进入状态。',strength:'主动建立沟通',detail:'在需要对齐信息时，你可能更愿意开口，把分散的想法连接起来。',risk:'交流挤占整理时间',riskDetail:'连续讨论可能让你来不及判断，哪些意见真正值得采取。',action:'开会前写下一个目标，会后留十分钟独立整理决定。',environment:'允许及时讨论、反馈较快的协作环境',relationship:'把分享的热情转成邀请，也给对方留出组织语言的时间。'},
 I:{title:'在安静中蓄力',meaning:'你的回答更偏向先独立整理，再与人交流。充足的准备时间和较少的打断，可能有助于发挥。',strength:'独立深入思考',detail:'你可能愿意先把问题想清楚，再提供较完整的观点。',risk:'想法迟迟没被看见',riskDetail:'如果一直等到足够完善，团队可能错过你的早期判断。',action:'在项目早期先分享一页草稿，用文字同步尚未成熟的想法。',environment:'支持专注时段、书面沟通与提前提供议程的团队',relationship:'需要独处时明确说明何时再聊，让安静成为可理解的需求。'},
 N:{title:'先看可能与关联',meaning:'你的回答更偏向模式、概念和未来的可能。面对模糊问题，你可能先寻找整体解释。',strength:'连接不同线索',detail:'你可能更容易从零散信息中提出新角度，或看见长期关联。',risk:'构想超过验证进度',riskDetail:'有吸引力的解释未必成立，方向也需要现实证据支持。',action:'把一个想法改写成可检验的假设，本周找一个真实案例验证。',environment:'有探索空间，同时能接触用户与事实的项目',relationship:'谈愿景时补充一个具体例子，减少彼此对含义的猜测。'},
 S:{title:'先看事实与落地',meaning:'你的回答更偏向可观察的事实、具体经验和实际步骤。清楚的示例可能比抽象概念更有帮助。',strength:'让方案可以执行',detail:'你可能善于追问资源、步骤与条件，帮助团队从讨论走向落实。',risk:'沿用经验的惯性',riskDetail:'熟悉的方法很省力，但新问题有时需要重新定义。',action:'开始执行前额外列一个替代方案，比较它与惯常方法的适用条件。',environment:'目标具体、资源清楚、能看到实际成果的工作',relationship:'表达关心时，也直接问对方需要行动帮助还是情绪回应。'},
 T:{title:'用标准帮助取舍',meaning:'你的回答更偏向一致的规则、逻辑与成本收益。做决定时，你可能先检查方案是否说得通。',strength:'厘清判断依据',detail:'你可能愿意指出推理缺口，帮助讨论围绕问题展开。',risk:'结论先于情绪回应',riskDetail:'一个合理的建议，如果缺少对处境的理解，可能难以被接受。',action:'提意见前先复述对方的目标，再解释判断标准与取舍。',environment:'允许质疑、标准透明、能就事论事的团队',relationship:'先确认对方想被倾听还是想找办法，再进入分析。'},
 F:{title:'把人的处境纳入决定',meaning:'你的回答更偏向感受、关系和具体处境。你可能会考虑一个决定如何影响参与其中的人。',strength:'注意协作中的感受',detail:'你可能更愿意照顾沟通方式，让不同处境的人参与讨论。',risk:'为维持和气延迟表达',riskDetail:'压下分歧会让边界和真实成本更难被看见。',action:'提出一次清晰而温和的拒绝：说明限制，再给一个可行替代。',environment:'尊重沟通、重视反馈、责任边界清楚的团队',relationship:'关心对方时也说出自己的需要，避免只让别人猜测。'},
 J:{title:'用结构获得推进感',meaning:'你的回答更偏向提前安排、明确责任和及时收尾。知道接下来做什么，可能让你更安心。',strength:'把目标拆成步骤',detail:'你可能愿意跟进承诺，帮助合作保持可预期的节奏。',risk:'过早锁定路径',riskDetail:'当新信息出现，原计划可能需要重新协商。',action:'为当前计划设置一个检查点，事先写明什么证据会让你调整。',environment:'优先级明确，同时允许按证据修订计划的项目',relationship:'把约定说清楚，也给临时变化保留协商空间。'},
 P:{title:'在变化中保留选择',meaning:'你的回答更偏向边做边看、即兴调整和开放选项。探索空间可能比过早定案更有吸引力。',strength:'根据变化调整方法',detail:'你可能愿意尝试替代路径，在现场信息变化时保持灵活。',risk:'选择太多导致难收尾',riskDetail:'持续探索有时会侵占交付时间，让伙伴难以安排。',action:'给下一次探索设定停止时间，先交付一个足够可用的版本。',environment:'有试验空间，也有明确交付节点的工作',relationship:'需要弹性时说明范围，对已承诺的事情及时同步变化。'},
 A:{title:'较快回到可行动的部分',meaning:'你的回答更偏向在评价或不确定面前保持平稳。这是本次自评倾向，并不意味着不会受压力影响。',strength:'维持行动节奏',detail:'遇到不理想的反馈时，你可能更容易把注意力放回下一步。',risk:'错过累积的疲劳',riskDetail:'感觉还能继续，不代表身体和注意力不需要恢复。',action:'每周记录睡眠、精力与任务负荷，给恢复安排固定时间。',environment:'反馈具体、能定期复盘工作负荷的环境',relationship:'不要假设别人也能很快放下，主动问一句对方是否需要支持。'},
 Tstress:{title:'更留意评价与不确定',meaning:'你的回答更偏向反复检查与关注反馈。这样的敏感可能帮助你发现问题，也可能消耗精力。',strength:'留意改进信号',detail:'你可能会认真回看自己的表现，发现值得调整的细节。',risk:'把一次结果等同于自己',riskDetail:'反复复盘可能从改进任务滑向否定整个人。',action:'把反馈写成事实、解释、下一步三栏；每次只选一项可控改进。',environment:'评价标准清晰、反馈具体、允许试错的环境',relationship:'不确定对方意思时先询问，避免把推测当作事实。'}
};
export function buildReport(result){
 const base=result.code.split('-')[0],hasX=base.includes('X');
 const [name,tagline]=profiles[base]||['多面探索者','你的回答跨越两端，值得结合场景继续理解。'];
 const selected=result.dimensions.map((d,i)=>{
  const g=guides[i===4&&d.letter==='T'?'Tstress':d.letter];
  if(d.boundary)return {axis:d.name,title:'在两种方式之间切换',meaning:`${d.name}的两侧分别为${d.leftPercent}%与${d.rightPercent}%，接近中点。本次没有明显偏向，建议分别回想工作与生活中的例子。`,strength:'保留不同做法',detail:`在${d.left}与${d.right}之间，你的总分没有明显拉开差距；这也可能来自不同题目的抵消。`,risk:'用一个字母概括全部场景',riskDetail:'中间得分不足以说明你在所有情境下都会灵活切换。',action:`记录三次与${d.name}有关的真实选择，写下情境与选择原因。`,environment:'允许根据任务选择做法、沟通期待清楚的环境',relationship:'直接说明当下需要，少用固定类型替自己或对方下结论。',strengthLabel:'倾向接近中点'};
  return {...g,axis:d.name,strengthLabel:Math.abs(d.leftPercent-50)>=25?'本次偏向较明显':'本次有一定偏向'};
 });
 return {name,tagline,hasX,selected,overview:`你在这次作答中呈现了${selected.slice(0,4).map(g=>g.title).join('、')}的组合。${result.dimensions.filter(d=>d.boundary).length?'部分维度接近中点，因此下方建议会保留多种可能。':'这些偏好可以帮助你描述工作习惯，但不能直接证明能力或预测职业成就。'}`,plan:[{day:'第 1–2 天',title:'观察一次真实的自己',body:selected[0].action},{day:'第 3–4 天',title:'做一个小规模实验',body:selected[1].action},{day:'第 5–6 天',title:'让合作更容易',body:selected[2].action},{day:'第 7 天',title:'复盘并保留有效的方法',body:'回看本周三次具体经历：什么让你更投入？什么让你耗竭？下周只保留一个有帮助的改变。'}]};
}
