export function narrativeText(result){const r=buildReport(result);return `\n\n${r.name}\n${r.tagline}\n${r.overview}\n\n`+r.selected.map(g=>`${g.axis} · ${g.title}\n${g.meaning}\n可能的优势：${g.strength}。${g.detail}\n留意：${g.risk}。${g.riskDetail}\n行动：${g.action}\n适合尝试的环境：${g.environment}\n关系建议：${g.relationship}`).join('\n\n')+'\n\n七天行动计划\n'+r.plan.map(p=>`${p.day} · ${p.title}\n${p.body}`).join('\n\n');}
